import org.junit.jupiter.api.io.TempDir;

/** Real index descriptions and the existing production cost projections. */
class LmdbIndexAccessShapeCompatibilityTest {

	@Test
	void actualIndexesPreserveBothProfilesForEveryMaskAndOrder(@TempDir Path directory) throws Exception {
		for (String indexes : List.of("spoc", "spoc,posc", "posc,spoc", "ocsp,cspo")) {
			Path storeDirectory = Files.createDirectory(directory.resolve(indexes.replace(',', '-')));
			try (TripleStore store = new TripleStore(storeDirectory.toFile(),
					new LmdbStoreConfig(indexes), null)) {
				store.startTransaction();
				store.storeTriple(1, 2, 3, 0, true);
				store.commit();
				try (var txn = store.getTxnManager().createReadTxn()) {
					var profile = store.indexAccessProfile(txn, true, false, -1, -1, -1);
					for (int mask = 0; mask < 16; mask++) {
						long s = (mask & 1) != 0 ? 1 : -1;
						long p = (mask & 2) != 0 ? 2 : -1;
						long o = (mask & 4) != 0 ? 3 : -1;
						long c = (mask & 8) != 0 ? 0 : -1;
						String label = "indexes=" + indexes + ", mask=" + mask;
						try (RecordIterator actual = store.getTriples(txn, s, p, o, c, true)) {
							int expected = prefixMask(actual.getIndexName(), mask);
							PackedCostEstimate packed = new PackedCostEstimate();
							store.describePackedAccessPath(mask, 2.5d, 7d, "shape-control", packed);
							assertEquals(expected, profile.prefixMask(null, mask), label);
							assertEquals(expected, packed.lookupComponentMask(), label);
							assertEquals(mask & ~expected, packed.missingLookupComponentMask(), label);
							assertEquals(Integer.bitCount(expected), packed.indexPrefixLength(), label);
							assertEquals(actual.getIndexName(), packed.indexName(), label);
							assertEquals(expected == 0 ? "fullScan" : mask == 15 ? "directLookup" : "prefixScan",
									packed.accessMode(), label);
							assertEquals(2.5d, packed.accessRows(), label);
							assertEquals(7d, packed.invocations(), label);
						}
						for (StatementOrder order : StatementOrder.values()) {
							String name = store.getIndexName(txn, order, s, p, o, c);
							if (name.isEmpty()) {
								assertEquals(-1, profile.prefixMask(order, mask), label + ", order=" + order);
							} else {
								try (RecordIterator actual = store.getTriples(txn, order, s, p, o, c, true)) {
									assertEquals(name, actual.getIndexName(), label + ", order=" + order);
									assertEquals(prefixMask(actual.getIndexName(), mask),
											profile.prefixMask(order, mask),
											label + ", order=" + order);
								}
							}
						}
					}
				}
			}
		}
	}

	@Test
	void realPackedLeafUsesIndexShapeAndExistingPhysicalPrice(@TempDir Path directory) throws Exception {
		var type = SimpleValueFactory.getInstance().createIRI("urn:population-owner:Patient");
		try (var fixture = new LmdbFrontierReadOwnershipContractTest.Fixture(directory, true);
				var read = fixture.read(FrontierLeafProbe.EXPLICIT, null, null)) {
			StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("p", RDF.TYPE), Var.of("o", type));
			PackedCostEstimate estimate = read.entry(pattern, null, (prepared, cascades) -> {
				var call = PackedCostTestSupport.preparedLeaf(prepared);
				try (var session = read.model().openSession(call.query())) {
					PackedCostEstimate result = new PackedCostEstimate();
					session.estimateLeaf(call.relationId(), call.emptyContext(), result);
					return result;
				}
			});
			assertEquals("posc", estimate.indexName());
			assertEquals(FrontierLeafProbe.PREDICATE | FrontierLeafProbe.OBJECT, estimate.lookupComponentMask());
			assertEquals(0, estimate.missingLookupComponentMask());
			assertEquals(2, estimate.indexPrefixLength());
			assertEquals("prefixScan", estimate.accessMode());
			assertEquals(2d, estimate.outputRows());
			assertEquals(2d, estimate.sequentialRows());
			assertEquals(1d, estimate.randomSeeks());
			assertEquals(1d, estimate.iteratorOpens());
			assertEquals(2d, estimate.resultRows());
			assertEquals(6d, estimate.workRows());
		}
	}

	private static int prefixMask(String fieldSequence, int boundMask) {
		int result = 0;
		for (char field : fieldSequence.toCharArray()) {
			int bit = switch (field) {
			case 's' -> 1;
			case 'p' -> 2;
			case 'o' -> 4;
			case 'c' -> 8;
			default -> throw new AssertionError("unknown index field " + field);
			};
			if ((boundMask & bit) == 0) {
				break;
			}
			result |= bit;
		}
		return result;
	}
}
